#pragma once

#include <CGAL/Polygon_2.h>
#include <CGAL/Exact_predicates_exact_constructions_kernel.h>
#include <vector>
#include <QWidget>
#include <QColor>
#include <QString>
#include <limits>
#include <optional>

using Kernel = CGAL::Exact_predicates_exact_constructions_kernel;
using Point = Kernel::Point_2;
using Polygon = CGAL::Polygon_2<Kernel>;

class MultiViewerDebug : public QWidget {
    Q_OBJECT
public:
    explicit MultiViewerDebug(QWidget* parent = nullptr);

    void addPolygon(const Polygon& poly, const QColor& color = Qt::black);
    void addPoints(const std::vector<Point>& pts);
    void addSpecialPolygon(const Polygon& poly);
    void addSpecialPoint(const Point& p);
    void clearAll();
    void clearSpecials();
    void clearPolygons();

    void addOriginalPoint(const Point& p);
    void addSimplifiedPoint(const Point& p);
    void addOriginalPoints(const std::vector<Point>& v);
    void addSimplifiedPoints(const std::vector<Point>& v);

    void clearOriginal();
    void clearSimplified();

    void addCurve(const std::vector<Point>& pts, const QColor& color, const QString& label);
    void clearCurves();

    const std::vector<Point>& original()   const { return original_; }
    const std::vector<Point>& simplified() const { return simplified_; }

    void setParameters(double delta, double epsilon);
    void setShowLabels(bool show);

    void markP0(const Point& p);
    void clearMarkedP0();
    void markPi(const Point& p);
    void clearMarkedPi();

    // Debug visualization for combined algorithms
    void addCvF(const Polygon& poly, const QColor& color = Qt::red);
    void addCvG(const Polygon& poly, const QColor& color = Qt::green);
    void addOldF(const Polygon& poly, const QColor& color = Qt::blue);
    void addOldG(const Polygon& poly, const QColor& color = Qt::yellow);
    void addCvS(const Polygon& poly, const QColor& color = Qt::magenta);
    void addOldS(const Polygon& poly, const QColor& color = Qt::cyan);
    void clearDebugPolygons();

    void addCvSimplifiedPoint(const Point& p);
    void addOldSimplifiedPoint(const Point& p);

protected:
    void paintEvent(QPaintEvent*) override;

private:
    struct ColoredPoly { Polygon poly; QColor color; QString label; };
    std::vector<ColoredPoly> polys_;
    std::vector<std::vector<Point>> pointSets_;
    std::vector<Point> original_;
    std::vector<Point> simplified_;
    std::vector<Point> cv_simplified_;
    std::vector<Point> old_simplified_;
    double delta_ = std::numeric_limits<double>::quiet_NaN();
    double epsilon_ = std::numeric_limits<double>::quiet_NaN();
    bool showLabels_ = false;
    std::optional<Point> marked_p0_;
    std::optional<Point> marked_pi_;
    std::vector<Polygon> special_polys_;
    std::vector<Point> special_points_;

    struct Curve { std::vector<Point> pts; QColor color; QString label; };
    std::vector<Curve> curves_;

    // Debug polygons for cv algorithm
    std::vector<ColoredPoly> cv_f_polys_;
    std::vector<ColoredPoly> cv_g_polys_;
    std::vector<ColoredPoly> cv_s_polys_;

    // Debug polygons for old algorithm
    std::vector<ColoredPoly> old_f_polys_;
    std::vector<ColoredPoly> old_g_polys_;
    std::vector<ColoredPoly> old_s_polys_;

    void compute_bbox(double& minx, double& miny, double& maxx, double& maxy) const;
};

void viewer_process_events();

#include "drawing_debug.h"
#include <QPainter>
#include <QPaintEvent>
#include <QApplication>
#include <algorithm>
#include <cmath>
#include <sstream>

MultiViewerDebug::MultiViewerDebug(QWidget* parent) : QWidget(parent) {
    setMinimumSize(800, 800);
    setBackgroundRole(QPalette::Base);
}

void MultiViewerDebug::addPolygon(const Polygon& poly, const QColor& color) {
    polys_.push_back({poly, color, ""});
}

void MultiViewerDebug::addPoints(const std::vector<Point>& pts) {
    pointSets_.push_back(pts);
}

void MultiViewerDebug::addSpecialPolygon(const Polygon& poly) {
    special_polys_.push_back(poly);
}

void MultiViewerDebug::addSpecialPoint(const Point& p) {
    special_points_.push_back(p);
}

void MultiViewerDebug::clearAll() {
    polys_.clear();
    pointSets_.clear();
    original_.clear();
    simplified_.clear();
    cv_simplified_.clear();
    old_simplified_.clear();
    special_polys_.clear();
    special_points_.clear();
    curves_.clear();
    clearDebugPolygons();
}

void MultiViewerDebug::clearSpecials() {
    special_polys_.clear();
    special_points_.clear();
}

void MultiViewerDebug::clearPolygons() {
    polys_.clear();
}

void MultiViewerDebug::addOriginalPoint(const Point& p) {
    original_.push_back(p);
}

void MultiViewerDebug::addSimplifiedPoint(const Point& p) {
    simplified_.push_back(p);
}

void MultiViewerDebug::addCvSimplifiedPoint(const Point& p) {
    cv_simplified_.push_back(p);
}

void MultiViewerDebug::addOldSimplifiedPoint(const Point& p) {
    old_simplified_.push_back(p);
}

void MultiViewerDebug::addOriginalPoints(const std::vector<Point>& v) {
    original_ = v;
}

void MultiViewerDebug::addSimplifiedPoints(const std::vector<Point>& v) {
    simplified_ = v;
}

void MultiViewerDebug::clearOriginal() {
    original_.clear();
}

void MultiViewerDebug::clearSimplified() {
    simplified_.clear();
}

void MultiViewerDebug::addCurve(const std::vector<Point>& pts, const QColor& color, const QString& label) {
    curves_.push_back({pts, color, label});
}

void MultiViewerDebug::clearCurves() {
    curves_.clear();
}

void MultiViewerDebug::setParameters(double delta, double epsilon) {
    delta_ = delta;
    epsilon_ = epsilon;
}

void MultiViewerDebug::setShowLabels(bool show) {
    showLabels_ = show;
}

void MultiViewerDebug::markP0(const Point& p) {
    marked_p0_ = p;
}

void MultiViewerDebug::clearMarkedP0() {
    marked_p0_ = std::nullopt;
}

void MultiViewerDebug::markPi(const Point& p) {
    marked_pi_ = p;
}

void MultiViewerDebug::clearMarkedPi() {
    marked_pi_ = std::nullopt;
}

void MultiViewerDebug::addCvF(const Polygon& poly, const QColor& color) {
    cv_f_polys_.push_back({poly, color, "CV_F"});
}

void MultiViewerDebug::addCvG(const Polygon& poly, const QColor& color) {
    cv_g_polys_.push_back({poly, color, "CV_G"});
}

void MultiViewerDebug::addOldF(const Polygon& poly, const QColor& color) {
    old_f_polys_.push_back({poly, color, "OLD_F"});
}

void MultiViewerDebug::addOldG(const Polygon& poly, const QColor& color) {
    old_g_polys_.push_back({poly, color, "OLD_G"});
}

void MultiViewerDebug::addCvS(const Polygon& poly, const QColor& color) {
    cv_s_polys_.push_back({poly, color, "CV_S"});
}

void MultiViewerDebug::addOldS(const Polygon& poly, const QColor& color) {
    old_s_polys_.push_back({poly, color, "OLD_S"});
}

void MultiViewerDebug::clearDebugPolygons() {
    cv_f_polys_.clear();
    cv_g_polys_.clear();
    cv_s_polys_.clear();
    old_f_polys_.clear();
    old_g_polys_.clear();
    old_s_polys_.clear();
}

void MultiViewerDebug::compute_bbox(double& minx, double& miny, double& maxx, double& maxy) const {
    const double INF = 1e100;
    minx = miny = INF;
    maxx = maxy = -INF;

    auto consider = [&](double x, double y) {
        minx = std::min(minx, x);
        miny = std::min(miny, y);
        maxx = std::max(maxx, x);
        maxy = std::max(maxy, y);
    };

    auto consider_point = [&](const Point& p) {
        consider(CGAL::to_double(p.x()), CGAL::to_double(p.y()));
    };

    for (const auto& cp : polys_) {
        for (auto it = cp.poly.vertices_begin(); it != cp.poly.vertices_end(); ++it) {
            consider_point(*it);
        }
    }
    for (const auto& cp : cv_f_polys_) {
        for (auto it = cp.poly.vertices_begin(); it != cp.poly.vertices_end(); ++it) {
            consider_point(*it);
        }
    }
    for (const auto& cp : cv_g_polys_) {
        for (auto it = cp.poly.vertices_begin(); it != cp.poly.vertices_end(); ++it) {
            consider_point(*it);
        }
    }
    for (const auto& cp : cv_s_polys_) {
        for (auto it = cp.poly.vertices_begin(); it != cp.poly.vertices_end(); ++it) {
            consider_point(*it);
        }
    }
    for (const auto& cp : old_f_polys_) {
        for (auto it = cp.poly.vertices_begin(); it != cp.poly.vertices_end(); ++it) {
            consider_point(*it);
        }
    }
    for (const auto& cp : old_g_polys_) {
        for (auto it = cp.poly.vertices_begin(); it != cp.poly.vertices_end(); ++it) {
            consider_point(*it);
        }
    }
    for (const auto& cp : old_s_polys_) {
        for (auto it = cp.poly.vertices_begin(); it != cp.poly.vertices_end(); ++it) {
            consider_point(*it);
        }
    }
    for (const auto& p : original_) consider_point(p);
    for (const auto& p : simplified_) consider_point(p);
    for (const auto& p : cv_simplified_) consider_point(p);
    for (const auto& p : old_simplified_) consider_point(p);
    for (const auto& p : special_points_) consider_point(p);
    for (const auto& ps : pointSets_) {
        for (const auto& p : ps) consider_point(p);
    }

    if (marked_p0_) consider_point(*marked_p0_);
    if (marked_pi_) consider_point(*marked_pi_);

    if (minx == INF) {
        minx = miny = -100;
        maxx = maxy = 100;
    }

    double pad = 20;
    minx -= pad; miny -= pad;
    maxx += pad; maxy += pad;
}

void MultiViewerDebug::paintEvent(QPaintEvent*) {
    QPainter painter(this);
    painter.setRenderHint(QPainter::Antialiasing);

    double minx, miny, maxx, maxy;
    compute_bbox(minx, miny, maxx, maxy);

    double width = maxx - minx;
    double height = maxy - miny;
    if (width <= 0) width = 1;
    if (height <= 0) height = 1;

    double scaleX = (width > 0) ? (double(this->width()) - 40) / width : 1;
    double scaleY = (height > 0) ? (double(this->height()) - 40) / height : 1;
    double scale = std::min(scaleX, scaleY);

    auto to_screen = [&](const Point& p) -> QPointF {
        double x = CGAL::to_double(p.x());
        double y = CGAL::to_double(p.y());
        return QPointF((x - minx) * scale + 20,
                       (maxy - y) * scale + 20);
    };

    painter.setBrush(Qt::NoBrush);

    // Draw bounding box outline
    painter.setPen(QPen(Qt::lightGray, 1));
    painter.drawRect(QRectF(to_screen(Point(minx, miny)), to_screen(Point(maxx, maxy))));

    // Draw CV F polygons (red, with transparency)
    painter.setPen(QPen(QColor(200, 50, 50, 200), 2));
    painter.setBrush(QColor(255, 100, 100, 40));
    for (const auto& cp : cv_f_polys_) {
        if (cp.poly.size() >= 3) {
            QPainterPath path;
            auto it = cp.poly.vertices_begin();
            path.moveTo(to_screen(*it));
            for (++it; it != cp.poly.vertices_end(); ++it) {
                path.lineTo(to_screen(*it));
            }
            path.closeSubpath();
            painter.drawPath(path);
        }
    }

    // Draw CV G polygons (green, with transparency)
    painter.setPen(QPen(QColor(50, 200, 50, 200), 2));
    painter.setBrush(QColor(100, 255, 100, 40));
    for (const auto& cp : cv_g_polys_) {
        if (cp.poly.size() >= 3) {
            QPainterPath path;
            auto it = cp.poly.vertices_begin();
            path.moveTo(to_screen(*it));
            for (++it; it != cp.poly.vertices_end(); ++it) {
                path.lineTo(to_screen(*it));
            }
            path.closeSubpath();
            painter.drawPath(path);
        }
    }

    // Draw CV S polygons (magenta, with transparency)
    painter.setPen(QPen(QColor(200, 50, 200, 200), 2));
    painter.setBrush(QColor(255, 100, 255, 40));
    for (const auto& cp : cv_s_polys_) {
        if (cp.poly.size() >= 3) {
            QPainterPath path;
            auto it = cp.poly.vertices_begin();
            path.moveTo(to_screen(*it));
            for (++it; it != cp.poly.vertices_end(); ++it) {
                path.lineTo(to_screen(*it));
            }
            path.closeSubpath();
            painter.drawPath(path);
        }
    }

    // Draw OLD F polygons (blue, with transparency)
    painter.setPen(QPen(QColor(50, 50, 200, 200), 2));
    painter.setBrush(QColor(100, 100, 255, 40));
    for (const auto& cp : old_f_polys_) {
        if (cp.poly.size() >= 3) {
            QPainterPath path;
            auto it = cp.poly.vertices_begin();
            path.moveTo(to_screen(*it));
            for (++it; it != cp.poly.vertices_end(); ++it) {
                path.lineTo(to_screen(*it));
            }
            path.closeSubpath();
            painter.drawPath(path);
        }
    }

    // Draw OLD G polygons (yellow, with transparency)
    painter.setPen(QPen(QColor(200, 200, 50, 200), 2));
    painter.setBrush(QColor(255, 255, 100, 40));
    for (const auto& cp : old_g_polys_) {
        if (cp.poly.size() >= 3) {
            QPainterPath path;
            auto it = cp.poly.vertices_begin();
            path.moveTo(to_screen(*it));
            for (++it; it != cp.poly.vertices_end(); ++it) {
                path.lineTo(to_screen(*it));
            }
            path.closeSubpath();
            painter.drawPath(path);
        }
    }

    // Draw OLD S polygons (cyan, with transparency)
    painter.setPen(QPen(QColor(50, 200, 200, 200), 2));
    painter.setBrush(QColor(100, 255, 255, 40));
    for (const auto& cp : old_s_polys_) {
        if (cp.poly.size() >= 3) {
            QPainterPath path;
            auto it = cp.poly.vertices_begin();
            path.moveTo(to_screen(*it));
            for (++it; it != cp.poly.vertices_end(); ++it) {
                path.lineTo(to_screen(*it));
            }
            path.closeSubpath();
            painter.drawPath(path);
        }
    }

    // Draw general polygons
    for (const auto& cp : polys_) {
        painter.setPen(QPen(cp.color, 1));
        if (cp.poly.size() >= 3) {
            QPainterPath path;
            auto it = cp.poly.vertices_begin();
            path.moveTo(to_screen(*it));
            for (++it; it != cp.poly.vertices_end(); ++it) {
                path.lineTo(to_screen(*it));
            }
            path.closeSubpath();
            painter.drawPath(path);
        }
    }

    // Draw special polygons
    painter.setPen(QPen(Qt::darkGreen, 1));
    for (const auto& p : special_polys_) {
        if (p.size() >= 3) {
            QPainterPath path;
            auto it = p.vertices_begin();
            path.moveTo(to_screen(*it));
            for (++it; it != p.vertices_end(); ++it) {
                path.lineTo(to_screen(*it));
            }
            path.closeSubpath();
            painter.drawPath(path);
        }
    }

    // Draw curves
    for (const auto& curve : curves_) {
        if (curve.pts.size() >= 2) {
            painter.setPen(QPen(curve.color, 2));
            auto it = curve.pts.begin();
            QPointF prev = to_screen(*it);
            for (++it; it != curve.pts.end(); ++it) {
                QPointF curr = to_screen(*it);
                painter.drawLine(prev, curr);
                prev = curr;
            }
        }
    }

    // Draw original points
    painter.setPen(QPen(Qt::black, 3));
    for (const auto& p : original_) {
        painter.drawPoint(to_screen(p));
    }

    // Draw simplified points (general)
    painter.setPen(QPen(Qt::red, 4));
    for (const auto& p : simplified_) {
        painter.drawPoint(to_screen(p));
    }

    // Draw CV simplified points (bright red)
    painter.setPen(QPen(QColor(200, 0, 0), 5));
    for (const auto& p : cv_simplified_) {
        painter.drawPoint(to_screen(p));
    }

    // Draw OLD simplified points (bright blue)
    painter.setPen(QPen(QColor(0, 0, 200), 5));
    for (const auto& p : old_simplified_) {
        painter.drawPoint(to_screen(p));
    }

    // Draw special points
    painter.setPen(QPen(Qt::darkGreen, 3));
    for (const auto& p : special_points_) {
        painter.drawPoint(to_screen(p));
    }

    // Draw marked p0
    if (marked_p0_) {
        painter.setPen(QPen(Qt::blue, 4));
        painter.drawEllipse(to_screen(*marked_p0_), 6, 6);
    }

    // Draw marked pi
    if (marked_pi_) {
        painter.setPen(QPen(Qt::darkMagenta, 4));
        painter.drawEllipse(to_screen(*marked_pi_), 6, 6);
    }

    // Draw legend
    int legendX = 10;
    int legendY = 10;
    int lineHeight = 18;
    painter.setFont(QFont("Arial", 9));

    // Legend background
    painter.setBrush(QColor(255, 255, 255, 220));
    painter.setPen(Qt::black);
    painter.drawRect(legendX, legendY, 140, 8 * lineHeight + 5);

    // Legend items
    QColor legendColors[] = {
        QColor(200, 50, 50),  // CV F - red
        QColor(50, 200, 50),  // CV G - green
        QColor(200, 50, 200), // CV S - magenta
        QColor(50, 50, 200),  // OLD F - blue
        QColor(200, 200, 50), // OLD G - yellow
        QColor(50, 200, 200), // OLD S - cyan
        QColor(200, 0, 0),    // CV simplified
        QColor(0, 0, 200)     // OLD simplified
    };
    const char* legendLabels[] = {
        "CV F polygons",
        "CV G polygons",
        "CV S polygons",
        "OLD F polygons",
        "OLD G polygons",
        "OLD S polygons",
        "CV simplified",
        "OLD simplified"
    };

    for (int i = 0; i < 8; ++i) {
        painter.setPen(QPen(legendColors[i], 3));
        painter.drawLine(legendX + 5, legendY + 5 + i * lineHeight + 6,
                        legendX + 25, legendY + 5 + i * lineHeight + 6);
        painter.setPen(Qt::black);
        painter.drawText(legendX + 30, legendY + 5 + i * lineHeight + 11, legendLabels[i]);
    }

    // Draw labels if enabled
    if (showLabels_) {
        painter.setFont(QFont("Arial", 8));
        int idx = 0;
        for (const auto& p : original_) {
            painter.setPen(Qt::black);
            painter.drawText(to_screen(p) + QPointF(5, -5), QString::number(idx));
            ++idx;
        }
    }

    // Draw info text
    if (!std::isnan(delta_) && !std::isnan(epsilon_)) {
        QString info = QString("delta=%1, epsilon=%2").arg(delta_).arg(epsilon_);
        painter.setPen(Qt::black);
        painter.setFont(QFont("Arial", 10));
        painter.drawText(width() - 180, height() - 10, info);
    }
}

static QApplication* g_app = nullptr;

void viewer_process_events() {
    if (g_app) {
        g_app->processEvents();
    }
}

