using Kernel = CGAL::Exact_predicates_exact_constructions_kernel;
using Point = Kernel::Point_2;
using Segment = Kernel::Segment_2;
using Ray = Kernel::Ray_2;
using Bbox = CGAL::Bbox_2;
using Rect = CGAL::Iso_rectangle_2<Kernel>;
using Polygon = CGAL::Polygon_2<Kernel>;
using Polygon_with_holes = CGAL::Polygon_with_holes_2<Kernel>;

constexpr double TOL = 1e-6;
constexpr double SQRT2 = 1.41421356237;

const double BMIN = -10000;
const double BMAX = 10000;
const double DATAMIN = -8000;
const double DATAMAX = 8000;
double DELTA = 200;
double EPSILON = 0.6;

double GRID_val() { return EPSILON * DELTA / (2 * SQRT2); }
double R_val() { return (1.0 + EPSILON / 2.0) * DELTA; }

bool showF = true;  // Show F polygons
bool showG = true;  // Show G polygons
bool showS = true;  // Show S polygons
bool showSimp = true;
bool showLabels = false;
std::string trace_path;
std::ofstream trace_stream;

static std::string point_summary(const Point& point) {
    std::ostringstream out;
    out << std::fixed << std::setprecision(12)
        << CGAL::to_double(point.x()) << ',' << CGAL::to_double(point.y());
    return out.str();
}

static std::string polygon_summary(const std::vector<Point>& polygon) {
    std::ostringstream out;
    out << "size=" << polygon.size();
    if (!polygon.empty()) {
        out << " verts=[";
        for (std::size_t i = 0; i < polygon.size(); ++i) {
            if (i != 0) out << ';';
            out << point_summary(polygon[i]);
        }
        out << ']';
    }
    Polygon poly(polygon.begin(), polygon.end());
    if (poly.size() >= 3) {
        try {
            out << " simple=" << (poly.is_simple() ? "1" : "0");
        } catch (...) {
            out << " simple=err";
        }
        try {
            out << " convex=" << (poly.is_convex() ? "1" : "0");
        } catch (...) {
            out << " convex=err";
        }
    }
    return out.str();
}

static void trace_line(const std::string& line) {
    if (!trace_stream.is_open()) return;
    trace_stream << line << '\n';
}

void print_help() {
    std::cout << "Usage: simplify_debug [options]\n"
              << "  --in <id>        Read input from data/taxi_simplified/<id>/original.txt\n"
              << "  --gui            Show GUI viewer\n"
              << "  -d <delta>       Override DELTA (default " << DELTA << ")\n"
              << "  -e <epsilon>     Override EPSILON (default " << EPSILON << ")\n"
              << "  -h               Show this help\n"
              << "  --no-f           Hide F polygons\n"
              << "  --no-g           Hide G polygons\n"
              << "  --no-s           Hide S polygons\n"
              << "  --no-simp        Hide simplified curves\n"
              << "  --trace-file <p> Write trace to file\n";
}

template<class Kernel, class Container>
void print_polygon(const CGAL::Polygon_2<Kernel, Container>& P) {
    typename CGAL::Polygon_2<Kernel, Container>::Vertex_const_iterator vit;
    std::cout << "[ " << P.size() << " vertices:";
    for (vit = P.vertices_begin(); vit != P.vertices_end(); ++vit)
        std::cout << " (" << *vit << ')';
    std::cout << " ]" << std::endl;
}

std::vector<cv::Point2f> to_cv_points(const std::vector<Point>& polygon) {
    std::vector<cv::Point2f> pts;
    pts.reserve(polygon.size());
    for (const auto& p : polygon) {
        pts.emplace_back(static_cast<float>(CGAL::to_double(p.x())),
                        static_cast<float>(CGAL::to_double(p.y())));
    }
    return pts;
}

std::vector<Point> from_cv_points(const std::vector<cv::Point2f>& pts) {
    std::vector<Point> polygon;
    polygon.reserve(pts.size());
    constexpr double ROUND_TO = 1e-9;
    for (const auto& p : pts) {
        double rx = std::round(p.x / ROUND_TO) * ROUND_TO;
        double ry = std::round(p.y / ROUND_TO) * ROUND_TO;
        polygon.emplace_back(rx, ry);
    }
    return polygon;
}

static std::vector<cv::Point2f> canonicalize_cv_polygon(const std::vector<cv::Point2f>& pts) {
    if (pts.size() < 3) return pts;
    std::size_t min_idx = 0;
    for (std::size_t i = 1; i < pts.size(); ++i) {
        if (pts[i].x < pts[min_idx].x ||
            (pts[i].x == pts[min_idx].x && pts[i].y < pts[min_idx].y)) {
            min_idx = i;
        }
    }
    std::vector<cv::Point2f> result;
    result.reserve(pts.size());
    for (std::size_t i = 0; i < pts.size(); ++i) {
        result.push_back(pts[(min_idx + i) % pts.size()]);
    }
    return result;
}

static std::vector<Polygon_with_holes> intersect_polygons_cv(const Polygon& lhs, const Polygon& rhs) {
    std::vector<Polygon_with_holes> result;
    std::vector<cv::Point2f> pts1 = to_cv_points(std::vector<Point>(lhs.vertices_begin(), lhs.vertices_end()));
    std::vector<cv::Point2f> pts2 = to_cv_points(std::vector<Point>(rhs.vertices_begin(), rhs.vertices_end()));

    if (pts1.size() < 3 || pts2.size() < 3) return result;

    try {
        std::vector<cv::Point2f> intersection;
        int polygonType = cv::intersectConvexConvex(pts1, pts2, intersection, true);

        if (polygonType < 0 || intersection.empty() || intersection.size() < 3) return result;

        constexpr float FLT_MAX_VAL = 3.4e+38f;
        bool has_invalid = false;
        for (const auto& p : intersection) {
            if (std::abs(p.x) >= FLT_MAX_VAL / 2 || std::abs(p.y) >= FLT_MAX_VAL / 2 ||
                std::isnan(p.x) || std::isnan(p.y) || std::isinf(p.x) || std::isinf(p.y)) {
                has_invalid = true;
                break;
            }
        }
        if (has_invalid) {
            CGAL::intersection(lhs, rhs, std::back_inserter(result));
            return result;
        }

        const float EPS = 1e-4f;
        std::vector<cv::Point2f> filtered;
        filtered.push_back(intersection[0]);
        for (std::size_t i = 1; i < intersection.size(); ++i) {
            const auto& curr = intersection[i];
            const auto& prev = filtered.back();
            if (std::abs(curr.x - prev.x) > EPS || std::abs(curr.y - prev.y) > EPS) {
                filtered.push_back(curr);
            }
        }
        if (filtered.size() > 1) {
            const auto& first = filtered.front();
            const auto& last = filtered.back();
            if (std::abs(first.x - last.x) < EPS && std::abs(first.y - last.y) < EPS) {
                filtered.pop_back();
            }
        }

        if (filtered.size() < 3) return result;

        std::vector<Point> cg_pts = from_cv_points(filtered);
        if (cg_pts.size() < 3) {
            CGAL::intersection(lhs, rhs, std::back_inserter(result));
            return result;
        }
        Polygon inter_poly(cg_pts.begin(), cg_pts.end());

        if (inter_poly.is_simple()) {
            if (inter_poly.is_counterclockwise_oriented()) {
                result.push_back(Polygon_with_holes(inter_poly));
            } else {
                inter_poly.reverse_orientation();
                result.push_back(Polygon_with_holes(inter_poly));
            }
        }
        return result;
    } catch (...) {
        return result;
    }
}

bool point_in_convex(const Point &p, const std::vector<Point> &poly, bool ccw = true) {
    for (size_t i = 0, n = poly.size(); i < n; ++i) {
        const auto &a = poly[i];
        const auto &b = poly[(i + 1) % n];
        if (CGAL::orientation(a, b, p) == (ccw ? CGAL::RIGHT_TURN : CGAL::LEFT_TURN))
            return false;
    }
    return true;
}

std::optional<Point> ray_hit_bbox(const Point &p, const Point &dir) {
    double px = CGAL::to_double(p.x()), py = CGAL::to_double(p.y());
    double dx = CGAL::to_double(dir.x()) - px,
           dy = CGAL::to_double(dir.y()) - py;
    double best = std::numeric_limits<double>::infinity(), hx = 0, hy = 0;
    auto consider = [&best, &hx, &hy, dx, dy, px, py](double t) {
        if (t <= 0) return;
        double x = px + t * dx, y = py + t * dy;
        if (x < BMIN - 1e-8 || x > BMAX + 1e-8 || y < BMIN - 1e-8 || y > BMAX + 1e-8) return;
        if (t < best) {
            best = t;
            hx = x;
            hy = y;
        }
    };
    if (std::abs(dx) > 1e-18) {
        consider((BMIN - px) / dx);
        consider((BMAX - px) / dx);
    }
    if (std::abs(dy) > 1e-18) {
        consider((BMIN - py) / dy);
        consider((BMAX - py) / dy);
    }
    if (!std::isfinite(best)) return std::nullopt;
    return Point(hx, hy);
}

enum class Bbox_edge {
    BL = 0, BOTTOM = 1, BR = 2, RIGHT = 3,
    TR = 4, TOP = 5, TL = 6, LEFT = 7,
};

static std::array<Point, 4> current_bbox_corner() {
    return {Point(BMIN, BMIN), Point(BMAX, BMIN), Point(BMAX, BMAX), Point(BMIN, BMAX)};
}

static std::vector<Point> current_bbox() {
    auto c = current_bbox_corner();
    return std::vector<Point>(c.begin(), c.end());
}

std::optional<Bbox_edge> which_edge(const Point &s) {
    double x = CGAL::to_double(s.x()), y = CGAL::to_double(s.y());
    bool on_left   = std::abs(x - BMIN) < TOL;
    bool on_right  = std::abs(x - BMAX) < TOL;
    bool on_bottom = std::abs(y - BMIN) < TOL;
    bool on_top    = std::abs(y - BMAX) < TOL;

    if (on_left && on_bottom) return Bbox_edge::BL;
    if (on_right && on_bottom) return Bbox_edge::BR;
    if (on_right && on_top) return Bbox_edge::TR;
    if (on_left && on_top) return Bbox_edge::TL;
    if (on_bottom) return Bbox_edge::BOTTOM;
    if (on_right)  return Bbox_edge::RIGHT;
    if (on_top)    return Bbox_edge::TOP;
    if (on_left)   return Bbox_edge::LEFT;
    return std::nullopt;
}

void append_rect_pts(std::vector<Point> &out, Bbox_edge from, Bbox_edge to, bool ccw) {
    auto corners = current_bbox_corner();
    auto next = [&](int idx) {
        return (idx + (ccw ? 1 : 7)) % 8;
    };
    int i = static_cast<int>(from);
    int j = static_cast<int>(to);
    if (i == j) return;
    for (int k = next(i); k != j; k = next(k)) {
        if ((k & 1) == 0) {
            int ci = k / 2;
            out.push_back(corners[ci]);
        }
    }
}

std::vector<Point> get_conv_from_grid(const Point &p) {
    const double px = CGAL::to_double(p.x());
    const double py = CGAL::to_double(p.y());
    const double r = R_val();
    const double GRID = GRID_val();
    const double r2 = r * r;
    int y_min = -(r / GRID) - 1;
    int y_max = -y_min;
    std::vector<Point> boundaries;
    boundaries.reserve(2 * y_max + 1);
    for (int y = y_min; y <= y_max; y++) {
        const double y_actual = y * GRID;
        const int x_min = -sqrt(r2 - y_actual * y_actual) / GRID - 1;
        boundaries.emplace_back(px + x_min * GRID, py + y_actual);
    }
    for (int y = y_min; y <= y_max; y++) {
        const double y_actual = y * GRID;
        const int x_max = (sqrt(r2 - y_actual * y_actual) / GRID) + 1;
        if (x_max != 0)
            boundaries.emplace_back(px + x_max * GRID, py + y_actual);
    }
    std::vector<Point> conv;
    CGAL::convex_hull_2(boundaries.begin(), boundaries.end(), std::back_inserter(conv));
    return conv;
}

std::vector<Point> get_points_from_grid(const Point &p) {
    const double px = CGAL::to_double(p.x());
    const double py = CGAL::to_double(p.y());
    const double r = R_val();
    const double GRID = GRID_val();
    const double r2 = r * r;
    int y_min = -(r / GRID) - 1;
    int y_max = -y_min;
    std::vector<Point> points;
    points.reserve(2 * y_max + 1);
    for (int y = y_min; y <= y_max; y++) {
        const double y_actual = y * GRID;
        const int x_min = -sqrt(r2 - y_actual * y_actual) / GRID - 1;
        const int x_max = -x_min;
        for (int x = x_min; x <= x_max; x++) {
            points.emplace_back(px + x * GRID, py + y_actual);
        }
    }
    return points;
}

std::vector<int> find_tangent_idx(const Point &p, const std::vector<Point> &S) {
    int n = S.size();
    std::vector<int> tangent;
    for (int i = 0; i < n; i++) {
        Point pred = S[(i - 1 + n) % n];
        Point now = S[i];
        Point succ = S[(i + 1 + n) % n];
        if (CGAL::orientation(p, pred, now)
                != CGAL::orientation(p, now, succ) &&
            CGAL::orientation(p, now, succ) != CGAL::COLLINEAR) {
            tangent.push_back(i);
        }
    }
    return tangent;
}

std::optional<Point> intersect_ray_with_rect(const Point& p, const Point& direction) {
    if (CGAL::to_double(CGAL::squared_distance(p, direction)) < TOL*TOL) return std::nullopt;
    Ray ray(p, direction);
    Bbox box(BMIN, BMIN, BMAX, BMAX);
    if (auto obj = CGAL::intersection(Rect(box), ray)) {
        if (const Point* ip = std::get_if<Point>(&*obj)) {
            if (CGAL::to_double(CGAL::squared_distance(*ip, p)) < TOL*TOL) return std::nullopt;
            return *ip;
        }
        if (const Segment* seg = std::get_if<Segment>(&*obj)) {
            const Point& a = seg->source();
            const Point& b = seg->target();
            double da = CGAL::to_double(CGAL::squared_distance(a, p));
            double db = CGAL::to_double(CGAL::squared_distance(b, p));
            if (da < TOL*TOL) return b;
            if (db < TOL*TOL) return a;
            return (da < db) ? a : b;
        }
    }
    return std::nullopt;
}

std::vector<Point> find_F(const Point& p, const std::vector<Point>& S) {
    if (S.size() == 1) return current_bbox();
    if (point_in_convex(p, S)) return current_bbox();
    std::vector<int> tangent = find_tangent_idx(p, S);
    if (tangent.size() != 2) {
        Polygon debug_polygon(S.begin(), S.end());
        std::cerr << "Unexpected tangent count: " << tangent.size();
        try { std::cerr << ", S.simple=" << (debug_polygon.is_simple() ? "yes" : "no"); } catch (...) {}
        try { std::cerr << ", S.convex=" << (debug_polygon.is_convex() ? "yes" : "no"); } catch (...) {}
        std::cerr << ", S.size=" << S.size() << "\n";
        return current_bbox();
    }

    std::optional<Point> hit1 = intersect_ray_with_rect(p, S[tangent[0]]);
    std::optional<Point> hit2 = intersect_ray_with_rect(p, S[tangent[1]]);
    if (!hit1 || !hit2) {
        std::cerr << "Ray doesn't intersect with bounding box!\n";
        return current_bbox();
    }
    std::optional<Bbox_edge> e1 = which_edge(hit1.value());
    std::optional<Bbox_edge> e2 = which_edge(hit2.value());

    int n = int(S.size());
    assert(n >= 3);
    CGAL_precondition(Polygon(S.begin(), S.end()).is_counterclockwise_oriented());

    std::vector<Point> F;
    if (CGAL::right_turn(p, S[tangent[0]], S[tangent[1]])) {
        std::copy(S.begin() + tangent[0], S.begin() + tangent[1] + 1, std::back_inserter(F));
        F.push_back(hit2.value());
        append_rect_pts(F, e2.value(), e1.value(), true);
        F.push_back(hit1.value());
    } else {
        std::copy(S.begin() + tangent[1], S.end(), std::back_inserter(F));
        std::copy(S.begin(), S.begin() + tangent[0] + 1, std::back_inserter(F));
        F.push_back(hit1.value());
        append_rect_pts(F, e1.value(), e2.value(), true);
        F.push_back(hit2.value());
    }
    if (!e1 || !e2) {
        std::cerr << "Cannot determine which Bbox edge the ray intersect with.\n";
        return current_bbox();
    }
    return F;
}

struct DebugStepData {
    int segment_start;
    int cur;
    int idx;
    std::vector<Point> P_i;
    std::vector<Point> S_i;
    std::vector<Point> F;
    std::vector<Point> G;
    std::vector<Point> new_S;
};

int get_longest_stab_cv(const std::vector<Point> &stream, int cur,
                        std::vector<Point> &simplified,
                        std::vector<DebugStepData>& debug_data,
                        MultiViewerDebug* viewer = nullptr) {
    const Point& p0 = stream[cur];
    const int segment_start = cur;
    int p0cur = cur;
    std::vector<Point> P = get_points_from_grid(p0);
    if (viewer) viewer->markP0(p0);
    std::array<Point, 2> buffer = {p0, p0};
    std::vector<std::vector<Point>> S(P.size(), std::vector<Point>{p0});
    int dead_cnt = 0;
    std::vector<int> dead(P.size());
    cur++;
    while (cur < int(stream.size())) {
        const Point& pi = stream[cur];
        std::vector<std::vector<Polygon_with_holes>> new_S(P.size());
        for (int i = 0; i < int(P.size()); i++) {
            if (dead[i]) continue;
            std::vector<Point> F = find_F(P[i], S[i]);
            std::vector<Point> Gi = get_conv_from_grid(pi);
            Polygon F_poly(F.begin(), F.end());
            Polygon Gi_poly(Gi.begin(), Gi.end());
            Polygon S_poly(S[i].begin(), S[i].end());

            new_S[i] = intersect_polygons_cv(F_poly, Gi_poly);

            for (auto& pwh : new_S[i]) {
                auto& outer = pwh.outer_boundary();
                if (outer.size() < 3) continue;
                std::size_t min_idx = 0;
                auto min_it = outer.vertices_begin();
                auto it = outer.vertices_begin();
                for (std::size_t i = 0; i < outer.size(); ++i, ++it) {
                    if (CGAL::compare_xy(*it, *min_it) == CGAL::SMALLER) {
                        min_it = it;
                        min_idx = i;
                    }
                }
                if (min_idx > 0) {
                    try {
                        std::vector<Point> new_vertices;
                        auto start_it = min_it;
                        for (std::size_t j = 0; j < outer.size(); ++j) {
                            new_vertices.push_back(*start_it);
                            ++start_it;
                            if (start_it == outer.vertices_end()) start_it = outer.vertices_begin();
                        }
                        Polygon new_poly(new_vertices.begin(), new_vertices.end());
                        if (outer.is_clockwise_oriented()) {
                            new_poly.reverse_orientation();
                        }
                        pwh = Polygon_with_holes(new_poly);
                    } catch (...) {}
                }
            }

            if (new_S[i].size() == 0) {
                dead[i] = true;
                dead_cnt++;
                continue;
            }
            assert(new_S[i].size() == 1);
            std::vector<Point> new_outer;
            std::copy(new_S[i].begin()->outer_boundary().vertices_begin(),
                      new_S[i].begin()->outer_boundary().vertices_end(),
                      std::back_inserter(new_outer));

            // Record debug data (only for first non-dead index per step)
            if (i == 0 || (i > 0 && !dead[i-1])) {
                DebugStepData d;
                d.segment_start = segment_start;
                d.cur = cur;
                d.idx = i;
                d.P_i = P[i];
                d.S_i = S[i];
                d.F = F;
                d.G = Gi;
                d.new_S = new_outer;
                debug_data.push_back(d);
            }

            buffer[0] = P[i];
            buffer[1] = *new_S[i].begin()->outer_boundary().vertices_begin();
        }
        if (dead_cnt == int(P.size())) break;
        if (viewer) viewer->addOriginalPoint(pi);
        if (viewer) viewer->markPi(pi);
        for (int i = 0; i < int(P.size()); i++) {
            if (dead[i]) continue;
            S[i].clear();
            std::copy(new_S[i].begin()->outer_boundary().vertices_begin(),
                      new_S[i].begin()->outer_boundary().vertices_end(),
                      std::back_inserter(S[i]));
        }
        cur++;
        if (viewer) viewer_process_events();
    }
    simplified.emplace_back(buffer[0]);
    simplified.emplace_back(buffer[1]);
    if (viewer && showSimp) viewer->addCvSimplifiedPoint(buffer[0]);
    if (viewer && showSimp) viewer->addCvSimplifiedPoint(buffer[1]);
    if (viewer) viewer->clearMarkedP0();
    if (viewer) viewer->clearMarkedPi();
    if (viewer) viewer_process_events();
    return cur;
}

int get_longest_stab_old(const std::vector<Point> &stream, int cur,
                         std::vector<Point> &simplified,
                         std::vector<DebugStepData>& debug_data,
                         MultiViewerDebug* viewer = nullptr) {
    const Point& p0 = stream[cur];
    const int segment_start = cur;
    int p0cur = cur;
    std::vector<Point> P = get_points_from_grid(p0);
    if (viewer) viewer->markP0(p0);
    std::array<Point, 2> buffer = {p0, p0};
    std::vector<std::vector<Point>> S(P.size(), std::vector<Point>{p0});
    int dead_cnt = 0;
    std::vector<int> dead(P.size());
    cur++;
    while (cur < int(stream.size())) {
        const Point& pi = stream[cur];
        std::vector<std::vector<Polygon_with_holes>> new_S(P.size());
        for (int i = 0; i < int(P.size()); i++) {
