            Polygon F_poly(F.begin(), F.end());
            Polygon Gi_poly(Gi.begin(), Gi.end());
            Polygon S_poly(S[i].begin(), S[i].end());

            CGAL::intersection(F_poly, Gi_poly, std::back_inserter(new_S[i]));

            if (new_S[i].size() == 0) {
                dead[i] = true;
                dead_cnt++;
                continue;
            }
            assert(new_S[i].size() == 1);

            std::vector<Point> new_outer;
            std::copy(new_S[i].begin()->outer_boundary().vertices_begin(),
                      new_S[i].begin()->outer_boundary().vertices_end(),
                      std::back_inserter(new_outer));

            // Record debug data
            DebugStepData d;
            d.segment_start = segment_start;
            d.cur = cur;
            d.idx = i;
            d.P_i = P[i];
            d.S_i = S[i];
            d.F = F;
            d.G = Gi;
            d.new_S = new_outer;
            debug_data.push_back(d);

            buffer[0] = P[i];
            buffer[1] = *new_S[i].begin()->outer_boundary().vertices_begin();
        }
        if (dead_cnt == int(P.size())) break;
        if (viewer) viewer->addOriginalPoint(pi);
        if (viewer) viewer->markPi(pi);
        for (int i = 0; i < int(P.size()); i++) {
            if (dead[i]) continue;
            S[i].clear();
            std::copy(new_S[i].begin()->outer_boundary().vertices_begin(),
                      new_S[i].begin()->outer_boundary().vertices_end(),
                      std::back_inserter(S[i]));
        }
        cur++;
        if (viewer) viewer_process_events();
    }
    simplified.emplace_back(buffer[0]);
    simplified.emplace_back(buffer[1]);
    if (viewer && showSimp) viewer->addOldSimplifiedPoint(buffer[0]);
    if (viewer && showSimp) viewer->addOldSimplifiedPoint(buffer[1]);
    if (viewer) viewer->clearMarkedP0();
    if (viewer) viewer->clearMarkedPi();
    if (viewer) viewer_process_events();
    return cur;
}

std::vector<Point> simplify_cv(const std::vector<Point> &stream,
                               std::vector<DebugStepData>& debug_data,
                               MultiViewerDebug* viewer = nullptr) {
    std::vector<Point> simplified;
    std::cout << "CV Simplifying...\n";
    int cur = 0;
    while (cur != int(stream.size())) {
        std::cout << "  CV segment at " << cur << '\n';
        cur = get_longest_stab_cv(stream, cur, simplified, debug_data, viewer);
    }
    std::cout << "CV Simplified!\n";
    return simplified;
}

std::vector<Point> simplify_old(const std::vector<Point> &stream,
                                 std::vector<DebugStepData>& debug_data,
                                 MultiViewerDebug* viewer = nullptr) {
    std::vector<Point> simplified;
    std::cout << "OLD Simplifying...\n";
    int cur = 0;
    while (cur != int(stream.size())) {
        std::cout << "  OLD segment at " << cur << '\n';
        cur = get_longest_stab_old(stream, cur, simplified, debug_data, viewer);
    }
    std::cout << "OLD Simplified!\n";
    return simplified;
}

int main(int argc, char** argv) {
    bool gui_flag = false;
    int test_case_no = -1;

    for (int i = 1; i < argc; ++i) {
        if (strcmp(argv[i],"--gui") == 0) gui_flag = true;
        else if (strcmp(argv[i],"-d") == 0 && i+1 < argc) {
            try { DELTA = std::stod(argv[++i]); } catch(...) {}
        }
        else if (strcmp(argv[i],"-e") == 0 && i+1 < argc) {
            try { EPSILON = std::stod(argv[++i]); } catch(...) {}
        }
        else if (strcmp(argv[i],"-h") == 0) { print_help(); return 0; }
        else if (strcmp(argv[i],"--in") == 0 && i+1 < argc) {
            try { test_case_no = std::stoi(argv[++i]); } catch(...) {}
        }
        else if (strcmp(argv[i],"--no-f") == 0) showF = false;
        else if (strcmp(argv[i],"--no-g") == 0) showG = false;
        else if (strcmp(argv[i],"--no-s") == 0) showS = false;
        else if (strcmp(argv[i],"--no-simp") == 0) showSimp = false;
        else if (strcmp(argv[i],"--trace-file") == 0 && i+1 < argc) {
            trace_path = argv[++i];
        }
    }

    if (test_case_no == -1 && argc >= 2 && argv[1][0] != '-') {
        try { test_case_no = std::stoi(argv[1]); } catch (...) {}
    }

    if (argc == 1 || test_case_no == -1) {
        print_help();
        return 0;
    }

    if (!trace_path.empty()) {
        trace_stream.open(trace_path);
    }

    std::vector<Point> stream;
    std::filesystem::path repo_root;
    try {
        auto exe = std::filesystem::canonical(argv[0]);
        auto dir = exe.parent_path();
        for (int i = 0; i < 5 && !dir.empty(); ++i) {
            if (std::filesystem::exists(dir / "data")) { repo_root = dir; break; }
            dir = dir.parent_path();
        }
    } catch (...) {}
    if (repo_root.empty()) {
        auto cwd = std::filesystem::current_path();
        repo_root = cwd;
    }

    auto simp_orig = repo_root / "data" / "taxi_simplified" / std::to_string(test_case_no) / "original.txt";
    std::ifstream fin(simp_orig.string());
    if (!fin) {
        std::cerr << "Cannot open " << simp_orig.string() << "\n";
        return 1;
    }
    int N = 0;
    if (!(fin >> N)) {
        std::cerr << "Empty or invalid input\n";
        return 1;
    }
    stream.reserve(N);
    for (int i = 0; i < N; ++i) {
        double x, y;
        if (!(fin >> x >> y)) {
            std::cerr << "Malformed pair at index " << i << "\n";
            return 1;
        }
        stream.emplace_back(x, y);
    }
    fin.close();

    std::cout << "Loaded " << N << " points\n";

    QApplication app(argc, argv);
    MultiViewerDebug viewer;
    MultiViewerDebug* vptr = nullptr;
    if (gui_flag) {
        vptr = &viewer;
        viewer.setParameters(DELTA, EPSILON);
        viewer.setShowLabels(showLabels);
        viewer.show();
    }

    std::vector<DebugStepData> cv_debug_data;
    std::vector<DebugStepData> old_debug_data;

    std::cout << "Running CV algorithm...\n";
    std::vector<Point> cv_simplified = simplify_cv(stream, cv_debug_data, vptr);
    std::cout << "CV result: " << cv_simplified.size() << " points\n";

    if (vptr) vptr->clearDebugPolygons();

    std::cout << "Running OLD algorithm...\n";
    std::vector<Point> old_simplified = simplify_old(stream, old_debug_data, vptr);
    std::cout << "OLD result: " << old_simplified.size() << " points\n";

    if (vptr) {
        std::cout << "Building debug visualization...\n";

        // Add all original points
        for (const auto& p : stream) {
            vptr->addOriginalPoint(p);
        }

        // Add CV polygons from debug data
        for (const auto& d : cv_debug_data) {
            if (showF) vptr->addCvF(Polygon(d.F.begin(), d.F.end()), QColor(200, 50, 50, 150));
            if (showG) vptr->addCvG(Polygon(d.G.begin(), d.G.end()), QColor(50, 200, 50, 150));
            if (showS) vptr->addCvS(Polygon(d.S_i.begin(), d.S_i.end()), QColor(200, 50, 200, 150));
        }

        // Add OLD polygons from debug data
        for (const auto& d : old_debug_data) {
            if (showF) vptr->addOldF(Polygon(d.F.begin(), d.F.end()), QColor(50, 50, 200, 150));
            if (showG) vptr->addOldG(Polygon(d.G.begin(), d.G.end()), QColor(200, 200, 50, 150));
            if (showS) vptr->addOldS(Polygon(d.S_i.begin(), d.S_i.end()), QColor(50, 200, 200, 150));
        }

        vptr->update();
    }

    // Compare results
    std::cout << "\n=== Comparison ===\n";
    std::cout << "CV simplified: " << cv_simplified.size() << " points\n";
    std::cout << "OLD simplified: " << old_simplified.size() << " points\n";

    if (cv_simplified.size() != old_simplified.size()) {
        std::cout << "WARNING: Different number of points!\n";
    }

    // Output results
    std::filesystem::path dir = repo_root / "data" / "taxi_simplified" / std::to_string(test_case_no);
    std::filesystem::create_directories(dir);

    std::ofstream cv_out(dir / "debug_cv.txt");
    cv_out << cv_simplified.size() << '\n';
    for (const auto& p : cv_simplified) {
        cv_out << CGAL::to_double(p.x()) << ' ' << CGAL::to_double(p.y()) << '\n';
    }
    cv_out.close();

    std::ofstream old_out(dir / "debug_old.txt");
    old_out << old_simplified.size() << '\n';
    for (const auto& p : old_simplified) {
        old_out << CGAL::to_double(p.x()) << ' ' << CGAL::to_double(p.y()) << '\n';
    }
    old_out.close();

    // Output debug data for analysis
    std::ofstream debug_csv(dir / "debug_comparison.csv");
    debug_csv << "algorithm,segment_start,cur,idx,F_size,G_size,S_size,new_S_size\n";
    for (const auto& d : cv_debug_data) {
        debug_csv << "cv," << d.segment_start << "," << d.cur << "," << d.idx
                  << "," << d.F.size() << "," << d.G.size()
                  << "," << d.S_i.size() << "," << d.new_S.size() << "\n";
    }
    for (const auto& d : old_debug_data) {
        debug_csv << "old," << d.segment_start << "," << d.cur << "," << d.idx
                  << "," << d.F.size() << "," << d.G.size()
                  << "," << d.S_i.size() << "," << d.new_S.size() << "\n";
    }
    debug_csv.close();

    std::cout << "Results written to " << dir << "\n";

    int gui_result = 0;
    if (gui_flag) {
        gui_result = app.exec();
    }

    return gui_result;
}

