#pragma once

#include <CGAL/Polygon_2.h>
#include <vector>
#include <QWidget>
#include <QColor>
#include <QString>
#include <limits>
#include <optional>

#include "geometry_kernel.h"

using Polygon = CGAL::Polygon_2<Kernel>;

class MultiViewerDebug : public QWidget {
    Q_OBJECT
public:
    explicit MultiViewerDebug(QWidget* parent = nullptr);

    void addPolygon(const Polygon& poly, const QColor& color = Qt::black);
    void addPoints(const std::vector<Point>& pts);
    void addSpecialPolygon(const Polygon& poly);
    void addSpecialPoint(const Point& p);
    void clearAll();
    void clearSpecials();
    void clearPolygons();

    void addOriginalPoint(const Point& p);
    void addSimplifiedPoint(const Point& p);
    void addOriginalPoints(const std::vector<Point>& v);
    void addSimplifiedPoints(const std::vector<Point>& v);

    void clearOriginal();
    void clearSimplified();

    void addCurve(const std::vector<Point>& pts, const QColor& color, const QString& label);
    void clearCurves();

    const std::vector<Point>& original()   const { return original_; }
    const std::vector<Point>& simplified() const { return simplified_; }

    void setParameters(double delta, double epsilon);
    void setShowLabels(bool show);

    void markP0(const Point& p);
    void clearMarkedP0();
    void markPi(const Point& p);
    void clearMarkedPi();

    // Debug visualization: separate CV and OLD F/G/S polygons
    void addCvF(const Polygon& poly, const QColor& color = Qt::red);
    void addCvG(const Polygon& poly, const QColor& color = Qt::green);
    void addCvS(const Polygon& poly, const QColor& color = Qt::magenta);
    void addOldF(const Polygon& poly, const QColor& color = Qt::blue);
    void addOldG(const Polygon& poly, const QColor& color = Qt::yellow);
    void addOldS(const Polygon& poly, const QColor& color = Qt::cyan);
    void clearDebugPolygons();

    void addCvSimplifiedPoint(const Point& p);
    void addOldSimplifiedPoint(const Point& p);

    // Visibility toggles for layers
    void setShowCvF(bool show) { show_cv_f_ = show; update(); }
    void setShowCvG(bool show) { show_cv_g_ = show; update(); }
    void setShowCvS(bool show) { show_cv_s_ = show; update(); }
    void setShowOldF(bool show) { show_old_f_ = show; update(); }
    void setShowOldG(bool show) { show_old_g_ = show; update(); }
    void setShowOldS(bool show) { show_old_s_ = show; update(); }

protected:
    void paintEvent(QPaintEvent*) override;

private:
    struct ColoredPoly { Polygon poly; QColor color; };
    std::vector<ColoredPoly> polys_;
    std::vector<std::vector<Point>> pointSets_;

    std::vector<Point> original_;
    std::vector<Point> simplified_;
    std::vector<Point> cv_simplified_;
    std::vector<Point> old_simplified_;

    double delta_   = std::numeric_limits<double>::quiet_NaN();
    double epsilon_ = std::numeric_limits<double>::quiet_NaN();
    bool showLabels_ = false;

    std::optional<Point> marked_p0_;
    std::optional<Point> marked_pi_;
    std::vector<Polygon> special_polys_;
    std::vector<Point> special_points_;

    struct Curve { std::vector<Point> pts; QColor color; QString label; };
    std::vector<Curve> curves_;

    // Debug polygons
    std::vector<ColoredPoly> cv_f_polys_;
    std::vector<ColoredPoly> cv_g_polys_;
    std::vector<ColoredPoly> cv_s_polys_;
    std::vector<ColoredPoly> old_f_polys_;
    std::vector<ColoredPoly> old_g_polys_;
    std::vector<ColoredPoly> old_s_polys_;

    // Layer visibility
    bool show_cv_f_ = true;
    bool show_cv_g_ = true;
    bool show_cv_s_ = true;
    bool show_old_f_ = true;
    bool show_old_g_ = true;
    bool show_old_s_ = true;

    void compute_bbox(double& minx, double& miny, double& maxx, double& maxy) const;
};

