void MultiViewerDebug::addPolygon(const Polygon& poly, const QColor& color) {
    polys_.push_back({poly, color});
    update();
}

void MultiViewerDebug::addPoints(const std::vector<Point>& pts) {
    pointSets_.push_back(pts);
    update();
}

void MultiViewerDebug::addSpecialPolygon(const Polygon& poly) {
    special_polys_.push_back(poly);
    update();
}

void MultiViewerDebug::addSpecialPoint(const Point& p) {
    special_points_.push_back(p);
    update();
}

void MultiViewerDebug::clearAll() {
    polys_.clear();
    pointSets_.clear();
    original_.clear();
    simplified_.clear();
    cv_simplified_.clear();
    old_simplified_.clear();
    special_polys_.clear();
    special_points_.clear();
    curves_.clear();
    clearDebugPolygons();
    update();
}

void MultiViewerDebug::clearSpecials() {
    special_polys_.clear();
    special_points_.clear();
    update();
}

void MultiViewerDebug::clearPolygons() {
    polys_.clear();
    update();
}

void MultiViewerDebug::addOriginalPoint(const Point& p) {
    original_.push_back(p);
    update();
}

void MultiViewerDebug::addSimplifiedPoint(const Point& p) {
    simplified_.push_back(p);
    update();
}

void MultiViewerDebug::addCvSimplifiedPoint(const Point& p) {
    cv_simplified_.push_back(p);
    update();
}

void MultiViewerDebug::addOldSimplifiedPoint(const Point& p) {
    old_simplified_.push_back(p);
    update();
}

void MultiViewerDebug::addOriginalPoints(const std::vector<Point>& v) {
    original_ = v;
    update();
}

void MultiViewerDebug::addSimplifiedPoints(const std::vector<Point>& v) {
    simplified_ = v;
    update();
}

void MultiViewerDebug::clearOriginal() {
    original_.clear();
    update();
}

void MultiViewerDebug::clearSimplified() {
    simplified_.clear();
    update();
}

void MultiViewerDebug::addCurve(const std::vector<Point>& pts, const QColor& color, const QString& label) {
    curves_.push_back({pts, color, label});
    update();
}

void MultiViewerDebug::clearCurves() {
    curves_.clear();
    update();
}

void MultiViewerDebug::setParameters(double delta, double epsilon) {
    delta_ = delta;
    epsilon_ = epsilon;
    update();
}

void MultiViewerDebug::setShowLabels(bool show) {
    showLabels_ = show;
    update();
}

void MultiViewerDebug::markP0(const Point& p) {
    marked_p0_ = p;
    update();
}

void MultiViewerDebug::clearMarkedP0() {
    marked_p0_ = std::nullopt;
    update();
