void MultiViewerDebug::compute_bbox(double& minx, double& miny, double& maxx, double& maxy) const {
    minx =  1e300; miny =  1e300;
    maxx = -1e300; maxy = -1e300;
    auto acc = [&](const Point& p){
        double x = CGAL::to_double(p.x());
        double y = CGAL::to_double(p.y());
        minx = std::min(minx,x); miny = std::min(miny,y);
        maxx = std::max(maxx,x); maxy = std::max(maxy,y);
    };
    auto acc_poly = [&](const Polygon& poly){
        for (auto v = poly.vertices_begin(); v != poly.vertices_end(); ++v) acc(*v);
    };
    for (auto& cp : polys_)           acc_poly(cp.poly);
    if (show_cv_f_)  for (auto& cp : cv_f_polys_)  acc_poly(cp.poly);
    if (show_cv_g_)  for (auto& cp : cv_g_polys_)  acc_poly(cp.poly);
    if (show_cv_s_)  for (auto& cp : cv_s_polys_)  acc_poly(cp.poly);
    if (show_old_f_) for (auto& cp : old_f_polys_) acc_poly(cp.poly);
    if (show_old_g_) for (auto& cp : old_g_polys_) acc_poly(cp.poly);
    if (show_old_s_) for (auto& cp : old_s_polys_) acc_poly(cp.poly);
    for (auto& p : original_)         acc(p);
    for (auto& p : simplified_)       acc(p);
    for (auto& p : cv_simplified_)    acc(p);
    for (auto& p : old_simplified_)   acc(p);
    for (auto& p : special_points_)   acc(p);
    for (auto& set : pointSets_)      for (auto& p : set) acc(p);
    if (marked_p0_) acc(*marked_p0_);
    if (marked_pi_) acc(*marked_pi_);
    if (!(minx <= maxx)) { minx = BMIN; maxx = BMAX; miny = BMIN; maxy = BMAX; }
}

void MultiViewerDebug::paintEvent(QPaintEvent*) {
    QPainter p(this);
    p.setRenderHint(QPainter::Antialiasing, true);

    double minx = BMIN, miny = BMIN, maxx = BMAX, maxy = BMAX;
    double dx = maxx - minx; if (dx == 0) dx = 1;
    double dy = maxy - miny; if (dy == 0) dy = 1;
    double margin = 30;
    int W = width(), H = height();
    double scale = std::min((W - 2*margin)/dx, (H - 2*margin)/dy);
    auto mapX = [&](double x){ return margin + (x - minx)*scale; };
    auto mapY = [&](double y){ return H - (margin + (y - miny)*scale); };

    p.fillRect(rect(), Qt::white);

    // Global bounding square outline
    {
        double x0 = mapX(BMIN), x1 = mapX(BMAX);
        double y0 = mapY(BMIN), y1 = mapY(BMAX);
        double left = std::min(x0, x1), top = std::min(y0, y1);
        double w = std::abs(x1-x0), h = std::abs(y1-y0);
        p.setBrush(Qt::NoBrush);
        p.setPen(QPen(QColor(80,80,80), 2, Qt::SolidLine));
        p.drawRect(QRectF(left, top, w, h));
    }

    // Helper to draw polygon with fill
    auto draw_polys = [&](const std::vector<ColoredPoly>& polys, int alpha = 50) {
        for (auto& cp : polys) {
            QPolygonF qp;
            for (auto v = cp.poly.vertices_begin(); v != cp.poly.vertices_end(); ++v)
                qp << QPointF(mapX(CGAL::to_double(v->x())),
                              mapY(CGAL::to_double(v->y())));
            QColor fill = cp.color;
            fill.setAlpha(alpha);
            p.setBrush(fill);
            p.setPen(QPen(cp.color, 2));
            p.drawPolygon(qp);
        }
    };

    // Draw F/G/S polygons in a nice order (old first, then CV)
    if (show_old_f_) draw_polys(old_f_polys_, 40);   // blue
    if (show_old_g_) draw_polys(old_g_polys_, 40);   // yellow
    if (show_old_s_) draw_polys(old_s_polys_, 40);  // cyan
    if (show_cv_f_)  draw_polys(cv_f_polys_, 40);   // red
    if (show_cv_g_)  draw_polys(cv_g_polys_, 40);   // green
    if (show_cv_s_)  draw_polys(cv_s_polys_, 40);  // magenta

    // General polygons
    p.setBrush(Qt::NoBrush);
    for (auto& cp : polys_) {
        QPolygonF qp;
        for (auto v = cp.poly.vertices_begin(); v != cp.poly.vertices_end(); ++v)
            qp << QPointF(mapX(CGAL::to_double(v->x())),
                          mapY(CGAL::to_double(v->y())));
        p.setPen(QPen(cp.color, 2));
        p.drawPolygon(qp);
    }

    // Special polygons (dashed orange)
    if (!special_polys_.empty()) {
        QColor edge(255, 140, 0), fill(255, 165, 0, 60);
        p.setBrush(fill);
        p.setPen(QPen(edge, 2, Qt::DashLine));
        for (auto& poly : special_polys_) {
            QPolygonF qp;
            for (auto v = poly.vertices_begin(); v != poly.vertices_end(); ++v)
                qp << QPointF(mapX(CGAL::to_double(v->x())),
                              mapY(CGAL::to_double(v->y())));
            p.drawPolygon(qp);
        }
        p.setBrush(Qt::NoBrush);
    }

    // Point sets
    p.setPen(Qt::NoPen);
    p.setBrush(Qt::black);
    for (auto& set : pointSets_)
        for (auto& pt : set)
            p.drawEllipse(QPointF(mapX(CGAL::to_double(pt.x())),
                                  mapY(CGAL::to_double(pt.y()))), 3, 3);

    // Original trajectory
    if (!original_.empty()) {
        p.setPen(QPen(Qt::darkGray, 2, Qt::SolidLine));
        for (size_t i = 1; i < original_.size(); ++i)
            p.drawLine(QPointF(mapX(CGAL::to_double(original_[i-1].x())),
                               mapY(CGAL::to_double(original_[i-1].y()))),
                       QPointF(mapX(CGAL::to_double(original_[i].x())),
                               mapY(CGAL::to_double(original_[i].y()))));
        p.setPen(Qt::NoPen);
        p.setBrush(Qt::darkGray);
        for (size_t i = 0; i < original_.size(); ++i) {
            const auto& pt = original_[i];
            QPointF pf(mapX(CGAL::to_double(pt.x())), mapY(CGAL::to_double(pt.y())));
            p.drawEllipse(pf, 2.5, 2.5);
            if (showLabels_) {
                p.setPen(Qt::black);
                p.drawText(pf + QPointF(5, -5), QString::number(i));
                p.setPen(Qt::NoPen);
            }
        }
    }

    // OLD simplified (cyan polyline + dots)
    if (!old_simplified_.empty()) {
        p.setPen(QPen(QColor(0, 180, 200), 3, Qt::SolidLine));
        for (size_t i = 1; i < old_simplified_.size(); ++i)
            p.drawLine(QPointF(mapX(CGAL::to_double(old_simplified_[i-1].x())),
                               mapY(CGAL::to_double(old_simplified_[i-1].y()))),
                       QPointF(mapX(CGAL::to_double(old_simplified_[i].x())),
                               mapY(CGAL::to_double(old_simplified_[i].y()))));
        p.setPen(Qt::NoPen);
        p.setBrush(QColor(0, 180, 200));
        for (auto& pt : old_simplified_)
            p.drawEllipse(QPointF(mapX(CGAL::to_double(pt.x())),
                                  mapY(CGAL::to_double(pt.y()))), 3.5, 3.5);
    }

    // CV simplified (red polyline + dots)
    if (!cv_simplified_.empty()) {
        p.setPen(QPen(Qt::red, 3, Qt::SolidLine));
        for (size_t i = 1; i < cv_simplified_.size(); ++i)
            p.drawLine(QPointF(mapX(CGAL::to_double(cv_simplified_[i-1].x())),
                               mapY(CGAL::to_double(cv_simplified_[i-1].y()))),
                       QPointF(mapX(CGAL::to_double(cv_simplified_[i].x())),
                               mapY(CGAL::to_double(cv_simplified_[i].y()))));
        p.setPen(Qt::NoPen);
        p.setBrush(Qt::red);
        for (auto& pt : cv_simplified_)
            p.drawEllipse(QPointF(mapX(CGAL::to_double(pt.x())),
                                  mapY(CGAL::to_double(pt.y()))), 3.5, 3.5);
    }

    // General simplified
    if (!simplified_.empty()) {
        p.setPen(QPen(Qt::darkMagenta, 2, Qt::SolidLine));
        for (size_t i = 1; i < simplified_.size(); ++i)
            p.drawLine(QPointF(mapX(CGAL::to_double(simplified_[i-1].x())),
                               mapY(CGAL::to_double(simplified_[i-1].y()))),
                       QPointF(mapX(CGAL::to_double(simplified_[i].x())),
                               mapY(CGAL::to_double(simplified_[i].y()))));
        p.setPen(Qt::NoPen);
        p.setBrush(Qt::darkMagenta);
        for (auto& pt : simplified_)
            p.drawEllipse(QPointF(mapX(CGAL::to_double(pt.x())),
                                  mapY(CGAL::to_double(pt.y()))), 3.0, 3.0);
    }

    // Colored curves
    for (const auto& c : curves_) {
        if (c.pts.empty()) continue;
        p.setPen(QPen(c.color, 2, Qt::SolidLine));
        for (size_t i = 1; i < c.pts.size(); ++i)
            p.drawLine(QPointF(mapX(CGAL::to_double(c.pts[i-1].x())),
                               mapY(CGAL::to_double(c.pts[i-1].y()))),
                       QPointF(mapX(CGAL::to_double(c.pts[i].x())),
                               mapY(CGAL::to_double(c.pts[i].y()))));
        p.setPen(Qt::NoPen);
        p.setBrush(c.color);
        for (auto& pt : c.pts)
            p.drawEllipse(QPointF(mapX(CGAL::to_double(pt.x())),
                                  mapY(CGAL::to_double(pt.y()))), 3.0, 3.0);
    }

    // Marked p0 (green)
    if (marked_p0_) {
        const auto& mp = *marked_p0_;
        double mx = mapX(CGAL::to_double(mp.x()));
        double my = mapY(CGAL::to_double(mp.y()));
        p.setPen(Qt::NoPen);
        p.setBrush(QColor(50, 200, 50));
        p.drawEllipse(QPointF(mx, my), 4.0, 4.0);
    }

    // Marked pi (orange)
    if (marked_pi_) {
        const auto& mp = *marked_pi_;
        double mx = mapX(CGAL::to_double(mp.x()));
        double my = mapY(CGAL::to_double(mp.y()));
        p.setPen(Qt::NoPen);
        p.setBrush(QColor(240, 140, 0));
        p.drawEllipse(QPointF(mx, my), 4.0, 4.0);
    }

    // Special points (cyan)
    if (!special_points_.empty()) {
        p.setPen(QPen(Qt::black, 1));
        p.setBrush(QColor(0, 200, 255));
        for (const auto& sp : special_points_)
            p.drawEllipse(QPointF(mapX(CGAL::to_double(sp.x())),
                                  mapY(CGAL::to_double(sp.y()))), 4.0, 4.0);
        p.setPen(Qt::black);
        p.setBrush(Qt::NoBrush);
    }

    // HUD (top-right)
    {
        const int pad = 8;
        const int marginTR = 10;
        const size_t n_orig = original_.size();
        const size_t n_cv = cv_simplified_.size();
        const size_t n_old = old_simplified_.size();
        QString ratioStr = (n_orig == 0) ? "ratio=-"
                                          : QString("CV:%1% OLD:%2% ")
                                              .arg(100.0*n_cv/n_orig, 0, 'f', 1)
                                              .arg(100.0*n_old/n_orig, 0, 'f', 1);
        QString eStr = QString("e=%1 ").arg(std::isfinite(epsilon_) ? QString::number(epsilon_, 'g', 4) : QString("-"));
        QString dStr = QString("d=%1").arg(std::isfinite(delta_) ? QString::number(delta_, 'g', 4) : QString("-"));
        QString line = ratioStr + eStr + dStr;

        QFontMetrics fm(p.font());
        int textW = fm.horizontalAdvance(line);
        int textH = fm.height();
        QRect rectBg(W - marginTR - (textW + 2*pad), marginTR, textW + 2*pad, textH + 2*pad);
        p.setPen(Qt::NoPen);
        p.setBrush(QColor(255, 255, 255, 210));
        p.drawRect(rectBg);
        p.setPen(Qt::black);
        p.drawText(rectBg.left() + pad, rectBg.top() + pad + fm.ascent(), line);
    }

    // Legend (top-left)
    {
        const int marginTL = 50;
        const int swatch = 10;
        const int pad = 6;
        int x0 = marginTL, y0 = marginTL;
        QFontMetrics fm(p.font());

        struct Entry { QColor color; QString text; };
        std::vector<Entry> entries;
        if (!original_.empty())      entries.push_back({Qt::darkGray,       QString("original (%1)").arg(qulonglong(original_.size()))});
        if (!cv_simplified_.empty()) entries.push_back({Qt::red,             QString("CV simplified (%1)").arg(qulonglong(cv_simplified_.size()))});
        if (!old_simplified_.empty()) entries.push_back({QColor(0,180,200),  QString("OLD simplified (%1)").arg(qulonglong(old_simplified_.size()))});
        if (!cv_f_polys_.empty() && show_cv_f_)  entries.push_back({Qt::red,             QString("CV F polys (%1)").arg(qulonglong(cv_f_polys_.size()))});
        if (!cv_g_polys_.empty() && show_cv_g_)  entries.push_back({Qt::green,           QString("CV G polys (%1)").arg(qulonglong(cv_g_polys_.size()))});
        if (!cv_s_polys_.empty() && show_cv_s_)  entries.push_back({Qt::magenta,         QString("CV S polys (%1)").arg(qulonglong(cv_s_polys_.size()))});
        if (!old_f_polys_.empty() && show_old_f_) entries.push_back({Qt::blue,           QString("OLD F polys (%1)").arg(qulonglong(old_f_polys_.size()))});
        if (!old_g_polys_.empty() && show_old_g_) entries.push_back({Qt::yellow,         QString("OLD G polys (%1)").arg(qulonglong(old_g_polys_.size()))});
        if (!old_s_polys_.empty() && show_old_s_) entries.push_back({QColor(0,200,200),  QString("OLD S polys (%1)").arg(qulonglong(old_s_polys_.size()))});
        if (!special_polys_.empty()) entries.push_back({QColor(255,140,0),   QString("special polys (%1)").arg(qulonglong(special_polys_.size()))});
        if (!special_points_.empty()) entries.push_back({QColor(0,200,255),  QString("special points (%1)").arg(qulonglong(special_points_.size()))});

        for (const auto& e : entries) {
            p.setPen(Qt::NoPen);
            p.setBrush(e.color);
            p.drawRect(x0, y0, swatch, swatch);
            p.setPen(Qt::black);
            p.drawText(x0 + swatch + pad, y0 + fm.ascent(), e.text);
            y0 += std::max(swatch, fm.height()) + 4;
        }
    }
}

